{
  "name": "Apex Bank - Premium Mobile Banking",
  "description": "A high-fidelity mobile banking application inspired by modern Nigerian fintech design, featuring account management, transfers, and a Gemini-powered financial assistant.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Transaction {
  id: string;
  name: string;
  type: 'debit' | 'credit';
  amount: number;
  date: string;
  bank?: string;
  avatar?: string;
}

export interface UserProfile {
  name: string;
  accountNumber: string;
  accountType: string;
  balance: number;
  avatar: string;
}

export enum AppScreen {
  DASHBOARD = 'DASHBOARD',
  PROFILE = 'PROFILE',
  TRANSFER = 'TRANSFER',
  ACTIVITY = 'ACTIVITY'
}

import React, { useState } from 'react';
import { AppScreen, UserProfile, Transaction } from './types';
import Dashboard from './components/Dashboard';
import Profile from './components/Profile';
import Transfer from './components/Transfer';
import BottomNav from './components/BottomNav';
import ChatAssistant from './components/ChatAssistant';

const INITIAL_USER: UserProfile = {
  name: 'Peter Abu-Ekpeshie',
  accountNumber: '0142468037',
  accountType: 'SAVINGS ACCOUNT',
  balance: 3500000.00,
  avatar: 'https://picsum.photos/seed/peter/200/200'
};

const INITIAL_TRANSACTIONS: Transaction[] = [
  { id: '1', name: 'Peter Abu-Ekpeshie', type: 'debit', amount: 5000, date: '14/05/19 . 1:00 AM', avatar: 'https://picsum.photos/seed/p1/200/200' },
  { id: '2', name: '0142468037', type: 'debit', amount: 5000, date: '14/05/19 . 1:00 AM', bank: 'GTBANK', avatar: 'https://picsum.photos/seed/p2/200/200' },
  { id: '3', name: 'Zion Ibitoye', type: 'debit', amount: 50.52, date: '14/05/19 . 1:00 AM', avatar: 'https://picsum.photos/seed/p3/200/200' },
  { id: '4', name: 'Peter Abu-Ekpeshie', type: 'debit', amount: 5000.43, date: '14/05/19 . 1:00 AM', avatar: 'https://picsum.photos/seed/p1/200/200' },
  { id: '5', name: 'Zion Ibitoye', type: 'debit', amount: 50.52, date: '14/05/19 . 1:00 AM', avatar: 'https://picsum.photos/seed/p3/200/200' },
];

const App: React.FC = () => {
  const [currentScreen, setCurrentScreen] = useState<AppScreen>(AppScreen.DASHBOARD);
  const [user, setUser] = useState<UserProfile>(INITIAL_USER);
  const [transactions, setTransactions] = useState<Transaction[]>(INITIAL_TRANSACTIONS);
  const [isChatOpen, setIsChatOpen] = useState(false);

  const renderScreen = () => {
    switch (currentScreen) {
      case AppScreen.DASHBOARD:
        return <Dashboard user={user} onTransfer={() => setCurrentScreen(AppScreen.TRANSFER)} />;
      case AppScreen.PROFILE:
        return <Profile user={user} />;
      case AppScreen.TRANSFER:
        return <Transfer 
          user={user} 
          transactions={transactions} 
          onBack={() => setCurrentScreen(AppScreen.DASHBOARD)}
          onTransferComplete={(amount) => {
            setUser(prev => ({ ...prev, balance: prev.balance - amount }));
            setCurrentScreen(AppScreen.DASHBOARD);
          }}
        />;
      default:
        return <Dashboard user={user} onTransfer={() => setCurrentScreen(AppScreen.TRANSFER)} />;
    }
  };

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-100 font-sans">
      <div className="relative w-full max-w-[430px] h-[932px] bg-white overflow-hidden shadow-2xl rounded-[3rem] border-8 border-gray-800 flex flex-col">
        {/* Mobile Status Bar Simulation */}
        <div className="flex justify-between items-center px-8 pt-10 pb-4 text-xs font-semibold">
          <span>9:41</span>
          <div className="flex items-center gap-1">
            <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M12 20c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zM12 4c-3.31 0-6 2.69-6 6s2.69 6 6 6 6-2.69 6-6-2.69-6-6-6z"/></svg>
            <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M15.67 4H14V2h-4v2H8.33C7.6 4 7 4.6 7 5.33v15.33C7 21.4 7.6 22 8.33 22h7.33c.74 0 1.34-.6 1.34-1.33V5.33C17 4.6 16.4 4 15.67 4z"/></svg>
          </div>
        </div>

        {/* Dynamic Content */}
        <div className="flex-1 overflow-y-auto custom-scrollbar">
          {renderScreen()}
        </div>

        {/* Gemini Chat Toggle */}
        <button 
          onClick={() => setIsChatOpen(!isChatOpen)}
          className="absolute right-6 bottom-24 bg-blue-600 hover:bg-blue-700 text-white p-4 rounded-full shadow-lg transition-transform active:scale-95 z-50"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
          </svg>
        </button>

        {isChatOpen && <ChatAssistant onClose={() => setIsChatOpen(false)} user={user} />}

        {/* Global Bottom Navigation */}
        <BottomNav 
          currentScreen={currentScreen} 
          onNavigate={setCurrentScreen} 
        />

        {/* iOS Home Indicator */}
        <div className="absolute bottom-2 left-1/2 -translate-x-1/2 w-32 h-1 bg-gray-300 rounded-full"></div>
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import { UserProfile } from '../types';

interface DashboardProps {
  user: UserProfile;
  onTransfer: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onTransfer }) => {
  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('en-NG', {
      style: 'currency',
      currency: 'NGN',
      minimumFractionDigits: 2,
    }).format(value);
  };

  return (
    <div className="p-6">
      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <button className="p-2 -ml-2 text-blue-900">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
          </svg>
        </button>
        <h1 className="text-blue-900 font-bold text-lg uppercase tracking-wider">Account Details</h1>
        <div className="w-6"></div>
      </div>

      {/* Account Card */}
      <div className="gradient-card p-6 rounded-2xl shadow-xl mb-10 relative overflow-hidden text-white">
        <div className="absolute top-0 right-0 p-4 opacity-10">
          <svg className="w-32 h-32" fill="currentColor" viewBox="0 0 24 24">
            <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/>
          </svg>
        </div>
        <div className="flex justify-between items-start mb-6">
          <span className="text-xs font-semibold opacity-80 uppercase tracking-widest">{user.accountType}</span>
          <span className="text-sm font-bold tracking-widest">{user.accountNumber}</span>
        </div>
        <div className="mb-6">
          <span className="text-sm font-medium opacity-80 block mb-1">NGN</span>
          <span className="text-3xl font-bold tracking-tight">{formatCurrency(user.balance).replace('NGN', '').trim()}</span>
        </div>
        <div className="flex items-center gap-2 text-xs font-medium">
          <div className="bg-white/20 p-1 rounded-full">
            <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 24 24">
              <path d="M13.5 19l-4.5-4.5 1.4-1.4 3.1 3.1 3.1-3.1 1.4 1.4-4.5 4.5zM13.5 5l4.5 4.5-1.4 1.4-3.1-3.1-3.1 3.1-1.4-1.4 4.5-4.5z"/>
            </svg>
          </div>
          <span>+ NGN 1,000 this week</span>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="flex justify-between items-center mb-10 px-2">
        <QuickActionButton icon="bill" label="Bills" />
        <QuickActionButton icon="transfer" label="Transfer" onClick={onTransfer} active />
        <QuickActionButton icon="airtime" label="Airtime" />
      </div>

      {/* Manage Account Section */}
      <div className="space-y-2">
        <h2 className="text-blue-900 font-bold text-sm uppercase tracking-widest mb-4">Manage Account</h2>
        <MenuButton 
          icon={<ClockIcon />} 
          title="Account Activity" 
          description="View all related account activity" 
          color="bg-blue-600" 
        />
        <MenuButton 
          icon={<FreezeIcon />} 
          title="Freeze Account" 
          description="Temporarily disable access to your account" 
          color="bg-sky-400" 
        />
        <MenuButton 
          icon={<LimitIcon />} 
          title="Set Transaction Limit" 
          description="Set a limit to how much you can withdraw" 
          color="bg-blue-800" 
        />
        <MenuButton 
          icon={<UpgradeIcon />} 
          title="Upgrade Account" 
          description="Upgrade your account to unlock more benefits" 
          color="bg-indigo-600" 
        />
      </div>
    </div>
  );
};

const QuickActionButton: React.FC<{ icon: string; label: string; onClick?: () => void; active?: boolean }> = ({ icon, label, onClick, active }) => {
  const icons = {
    bill: <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />,
    transfer: <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" />,
    airtime: <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 18h.01M8 21h8a2 2 0 002-2V5a2 2 0 00-2-2H8a2 2 0 00-2 2v14a2 2 0 002 2z" />
  };

  return (
    <button onClick={onClick} className="flex flex-col items-center gap-2 transition-transform active:scale-90">
      <div className={`w-14 h-14 rounded-full flex items-center justify-center border-2 transition-colors ${active ? 'bg-white border-blue-600 text-blue-600 shadow-md' : 'bg-white border-gray-100 text-gray-400'}`}>
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          {icons[icon as keyof typeof icons]}
        </svg>
      </div>
      <span className={`text-[10px] font-bold uppercase tracking-widest ${active ? 'text-blue-900' : 'text-gray-400'}`}>{label}</span>
    </button>
  );
};

const MenuButton: React.FC<{ icon: React.ReactNode; title: string; description: string; color: string }> = ({ icon, title, description, color }) => (
  <button className="w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors group">
    <div className="flex items-center gap-4">
      <div className={`${color} w-8 h-8 rounded-full flex items-center justify-center text-white shadow-sm`}>
        {icon}
      </div>
      <div className="text-left">
        <h3 className="text-sm font-bold text-gray-800">{title}</h3>
        <p className="text-xs text-gray-400">{description}</p>
      </div>
    </div>
    <div className="w-6 h-6 bg-gray-100 rounded-full flex items-center justify-center group-hover:bg-blue-600 group-hover:text-white transition-colors">
      <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
      </svg>
    </div>
  </button>
);

const ClockIcon = () => (
  <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zM12 20c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm.5-13H11v6l5.25 3.15.75-1.23-4.5-2.67z"/></svg>
);
const FreezeIcon = () => (
  <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M17 12c0 2.76-2.24 5-5 5s-5-2.24-5-5 2.24-5 5-5 5 2.24 5 5zm-5-3c-1.66 0-3 1.34-3 3s1.34 3 3 3 3-1.34 3-3-1.34-3-3-3z"/></svg>
);
const LimitIcon = () => (
  <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M2 7h20v10H2z"/></svg>
);
const UpgradeIcon = () => (
  <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M12 8l-6 6 1.41 1.41L12 10.83l4.59 4.58L18 14z"/></svg>
);

export default Dashboard;

import React from 'react';
import { UserProfile } from '../types';

interface ProfileProps {
  user: UserProfile;
}

const Profile: React.FC<ProfileProps> = ({ user }) => {
  return (
    <div className="bg-blue-900 min-h-full flex flex-col">
      <div className="p-8 pt-12 flex flex-col items-center text-white">
        {/* Profile Header */}
        <div className="relative mb-6">
          <img 
            src={user.avatar} 
            alt={user.name} 
            className="w-24 h-24 rounded-full border-4 border-white/20 shadow-xl"
          />
          <button className="absolute bottom-0 right-0 bg-red-500 p-2 rounded-full border-2 border-blue-900 shadow-lg">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
            </svg>
          </button>
        </div>
        <h2 className="text-xl font-bold mb-1">{user.name}</h2>
        <button className="text-[10px] text-white/60 uppercase font-bold tracking-widest hover:text-white transition-colors mb-8">Update picture</button>
      </div>

      <div className="flex-1 bg-white rounded-t-[3rem] p-8 shadow-inner-xl">
        <div className="mb-8">
          <h3 className="text-blue-900 font-bold text-xs uppercase tracking-widest mb-6">General</h3>
          <div className="space-y-6">
            <ProfileMenuItem title="App Sound" toggle />
            <ProfileMenuItem title="Share App" />
            <ProfileMenuItem title="Refer a friend" hasArrow />
            <ProfileMenuItem title="Support" hasArrow />
            <ProfileMenuItem title="Live Chat" hasArrow />
            <ProfileMenuItem title="F.A.Qs" hasArrow />
            <ProfileMenuItem title="View BVN" hasArrow />
            <ProfileMenuItem title="Submit Complaint" hasArrow />
          </div>
        </div>

        <div>
          <h3 className="text-blue-900 font-bold text-xs uppercase tracking-widest mb-6">Security</h3>
          <div className="bg-blue-50/50 rounded-2xl p-4">
            <ProfileMenuItem title="Change Password" hasArrow />
          </div>
        </div>
      </div>
    </div>
  );
};

const ProfileMenuItem: React.FC<{ title: string; hasArrow?: boolean; toggle?: boolean }> = ({ title, hasArrow, toggle }) => (
  <div className="flex items-center justify-between py-2 group cursor-pointer">
    <span className="text-sm font-semibold text-gray-700 group-hover:text-blue-600 transition-colors">{title}</span>
    {toggle && (
      <div className="w-10 h-6 bg-gray-200 rounded-full relative p-1 cursor-pointer">
        <div className="w-4 h-4 bg-white rounded-full shadow-sm"></div>
      </div>
    )}
    {hasArrow && (
      <svg className="w-4 h-4 text-blue-900" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
      </svg>
    )}
  </div>
);

export default Profile;

import React, { useState } from 'react';
import { UserProfile, Transaction } from '../types';

interface TransferProps {
  user: UserProfile;
  transactions: Transaction[];
  onBack: () => void;
  onTransferComplete: (amount: number) => void;
}

const Transfer: React.FC<TransferProps> = ({ user, transactions, onBack, onTransferComplete }) => {
  const [step, setStep] = useState<'options' | 'input'>('options');
  const [amount, setAmount] = useState('');

  const handleTransfer = () => {
    const amt = parseFloat(amount);
    if (isNaN(amt) || amt <= 0 || amt > user.balance) {
      alert("Invalid amount or insufficient balance");
      return;
    }
    onTransferComplete(amt);
  };

  return (
    <div className="bg-blue-900 min-h-full flex flex-col">
      <div className="p-8 pt-12 text-white">
        <div className="flex justify-between items-center mb-8">
          <button onClick={onBack} className="p-2 -ml-2 text-white hover:bg-white/10 rounded-full transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
          <div className="bg-white/20 p-3 rounded-full">
            <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24">
              <path d="M19 13H5v-2h14v2z"/>
              <path d="M12 5l-7 7 7 7 1.41-1.41L7.83 12l5.58-5.59L12 5z" transform="rotate(180, 12, 12)"/>
            </svg>
          </div>
        </div>

        <h2 className="text-xl font-bold mb-2">Funds Transfer</h2>
        <p className="text-xs text-white/60 mb-8">How would you like to transfer Money?</p>

        <div className="space-y-4">
          <TransferOption title="Send to Beneficiary" hasArrow onClick={() => setStep('input')} />
          <TransferOption title="Send to Account Number" hasArrow onClick={() => setStep('input')} />
        </div>
      </div>

      <div className="flex-1 bg-white rounded-t-[3rem] p-8 mt-4 shadow-inner-xl">
        {step === 'options' ? (
          <>
            <div className="flex justify-center mb-8">
              <div className="bg-blue-50 text-blue-900 px-6 py-2 rounded-full text-[10px] font-bold uppercase tracking-widest">
                Recent Transfers
              </div>
            </div>

            <div className="space-y-4">
              {transactions.map(tx => (
                <div key={tx.id} className="flex items-center justify-between p-2 hover:bg-gray-50 rounded-xl transition-colors cursor-pointer">
                  <div className="flex items-center gap-4">
                    <img src={tx.avatar} alt={tx.name} className="w-10 h-10 rounded-full bg-gray-100" />
                    <div>
                      <h4 className="text-sm font-bold text-gray-800">{tx.name}</h4>
                      <p className="text-[10px] text-gray-400 font-medium uppercase">{tx.bank ? `${tx.bank} . ` : ''}{tx.date}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-3 text-right">
                    <span className="text-sm font-bold text-gray-800">-{new Intl.NumberFormat('en-NG', { style: 'currency', currency: 'NGN' }).format(tx.amount)}</span>
                    <div className="w-6 h-6 bg-green-100 text-green-600 rounded-full flex items-center justify-center">
                      <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41L9 16.17z"/></svg>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </>
        ) : (
          <div className="animate-fade-in">
            <h3 className="text-blue-900 font-bold text-lg mb-6">Enter Amount</h3>
            <div className="relative mb-8">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold">₦</span>
              <input 
                type="number" 
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="0.00"
                className="w-full bg-gray-50 border-2 border-transparent focus:border-blue-600 rounded-2xl py-6 pl-12 pr-4 text-2xl font-bold outline-none transition-all"
              />
            </div>
            <p className="text-sm text-gray-500 mb-8 text-center">Available Balance: ₦{user.balance.toLocaleString()}</p>
            <button 
              onClick={handleTransfer}
              className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-5 rounded-2xl shadow-xl transition-transform active:scale-95"
            >
              Continue
            </button>
            <button 
              onClick={() => setStep('options')}
              className="w-full mt-4 text-gray-400 font-bold py-2 text-sm hover:text-gray-600"
            >
              Cancel
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

const TransferOption: React.FC<{ title: string; hasArrow?: boolean; onClick: () => void }> = ({ title, hasArrow, onClick }) => (
  <button onClick={onClick} className="w-full flex items-center justify-between p-5 bg-white/10 hover:bg-white/20 border border-white/10 rounded-2xl transition-all group">
    <span className="text-sm font-bold">{title}</span>
    {hasArrow && (
      <svg className="w-5 h-5 group-hover:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 8l4 4m0 0l-4 4m4-4H3" />
      </svg>
    )}
  </button>
);

export default Transfer;

import React from 'react';
import { AppScreen } from '../types';

interface BottomNavProps {
  currentScreen: AppScreen;
  onNavigate: (screen: AppScreen) => void;
}

const BottomNav: React.FC<BottomNavProps> = ({ currentScreen, onNavigate }) => {
  return (
    <div className="bg-white border-t border-gray-100 px-6 py-4 flex justify-between items-center z-10">
      <NavItem 
        isActive={currentScreen === AppScreen.DASHBOARD} 
        onClick={() => onNavigate(AppScreen.DASHBOARD)}
        icon={<HomeIcon />}
      />
      <NavItem 
        isActive={currentScreen === AppScreen.ACTIVITY} 
        onClick={() => onNavigate(AppScreen.ACTIVITY)}
        icon={<ActivityIcon />}
      />
      <NavItem 
        isActive={false} 
        onClick={() => {}}
        icon={<SupportIcon />}
      />
      <NavItem 
        isActive={currentScreen === AppScreen.PROFILE} 
        onClick={() => onNavigate(AppScreen.PROFILE)}
        icon={<ProfileIcon />}
      />
    </div>
  );
};

const NavItem: React.FC<{ isActive: boolean; icon: React.ReactNode; onClick: () => void }> = ({ isActive, icon, onClick }) => (
  <button onClick={onClick} className={`p-3 rounded-2xl transition-all ${isActive ? 'bg-blue-600 text-white shadow-lg scale-110' : 'text-gray-400 hover:text-blue-900'}`}>
    {icon}
  </button>
