import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getFinancialAdvice = async (prompt: string, balance: number) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction: `You are a helpful and professional financial assistant for Apex Bank. 
        The user's current balance is ₦${balance.toLocaleString()}. 
        Keep your answers concise, friendly, and focused on financial well-being. 
        You can help with app navigation, saving tips, and investment basics.`,
        temperature: 0.7,
      },
    });
    return response.text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "I'm having trouble connecting right now. Please try again later!";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { getFinancialAdvice } from '../services/gemini';
import { UserProfile } from '../types';

interface Message {
  text: string;
  sender: 'user' | 'bot';
}

const ChatAssistant: React.FC<{ onClose: () => void; user: UserProfile }> = ({ onClose, user }) => {
  const [messages, setMessages] = useState<Message[]>([
    { text: `Hi ${user.name}! I'm your Apex Assistant. How can I help you today?`, sender: 'bot' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { text: userMsg, sender: 'user' }]);
    setIsLoading(true);

    const botResponse = await getFinancialAdvice(userMsg, user.balance);
    setMessages(prev => [...prev, { text: botResponse || 'Sorry, I missed that.', sender: 'bot' }]);
    setIsLoading(false);
  };

  return (
    <div className="absolute inset-x-0 bottom-20 top-20 bg-white shadow-2xl z-40 rounded-t-3xl flex flex-col animate-slide-up">
      <div className="p-6 bg-blue-600 text-white rounded-t-3xl flex justify-between items-center">
        <div>
          <h3 className="font-bold">Apex Smart Assistant</h3>
          <p className="text-[10px] text-blue-100 uppercase tracking-widest font-semibold">Online & ready to help</p>
        </div>
        <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      <div ref={scrollRef} className="flex-1 p-6 overflow-y-auto space-y-4 custom-scrollbar">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-4 rounded-2xl text-sm ${m.sender === 'user' ? 'bg-blue-600 text-white rounded-br-none' : 'bg-gray-100 text-gray-800 rounded-bl-none'}`}>
              {m.text}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-gray-100 p-4 rounded-2xl rounded-bl-none animate-pulse text-xs font-bold text-gray-400">
              Assistant is thinking...
            </div>
          </div>
        )}
      </div>

      <div className="p-4 border-t border-gray-100 flex gap-2">
        <input 
          type="text" 
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSend()}
          placeholder="Ask about saving tips..."
          className="flex-1 bg-gray-50 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600"
        />
        <button 
          onClick={handleSend}
          disabled={isLoading}
          className="bg-blue-600 text-white p-3 rounded-xl disabled:opacity-50"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
          </svg>
        </button>
      </div>
    </div>
  );
};

export default ChatAssistant;

