const App: React.FC = () => {
  const [currentScreen, setCurrentScreen] = useState<AppScreen>(AppScreen.DASHBOARD);
  const [user, setUser] = useState<UserProfile>(INITIAL_USER);
  const [transactions, setTransactions] = useState<Transaction[]>(INITIAL_TRANSACTIONS);
  const [isChatOpen, setIsChatOpen] = useState(false);

  const handleInvestmentComplete = (amount: number) => {
    setUser(prev => ({
      ...prev,
      balance: prev.balance - amount,
      investmentBalance: prev.investmentBalance + amount
    }));

    const newTx: Transaction = {
      id: Date.now().toString(),
      name: 'Apex High-Yield Fund Subscription',
      type: 'debit',
      amount: amount,
      date: new Date().toLocaleString(),
      avatar: 'https://picsum.photos/seed/invest/200/200'
    };
    setTransactions([newTx, ...transactions]);
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case AppScreen.DASHBOARD:
        return <Dashboard 
          user={user} 
          onTransfer={() => setCurrentScreen(AppScreen.TRANSFER)} 
          onViewActivity={() => setCurrentScreen(AppScreen.ACTIVITY)}
        />;
      case AppScreen.PROFILE:
        return <Profile user={user} />;
      case AppScreen.TRANSFER:
        return <Transfer 
          user={user} 
          transactions={transactions} 
          onBack={() => setCurrentScreen(AppScreen.DASHBOARD)}
          onTransferComplete={(amount) => {
            const newTx: Transaction = {
              id: Date.now().toString(),
              name: 'Transfer Out',
              type: 'debit',
              amount: amount,
              date: new Date().toLocaleString(),
              avatar: 'https://picsum.photos/seed/tx/200/200'
            };
            setTransactions([newTx, ...transactions]);
            setUser(prev => ({ ...prev, balance: prev.balance - amount }));
            setCurrentScreen(AppScreen.DASHBOARD);
          }}
        />;
      case AppScreen.ACTIVITY:
        return <Activity transactions={transactions} />;
      case AppScreen.INVESTMENT:
        return <Investment user={user} onInvestmentComplete={handleInvestmentComplete} />;
      default:
        return <Dashboard 
          user={user} 
          onTransfer={() => setCurrentScreen(AppScreen.TRANSFER)} 
          onViewActivity={() => setCurrentScreen(AppScreen.ACTIVITY)}
        />;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 font-sans flex flex-col">
      <div className="flex-1 w-full max-w-2xl mx-auto bg-white shadow-xl min-h-screen flex flex-col relative">
        <div className="flex-1 overflow-y-auto custom-scrollbar pb-24">
          {renderScreen()}
        </div>

        <button 
          onClick={() => setIsChatOpen(!isChatOpen)}
          className="fixed bottom-24 right-6 lg:right-[calc(50%-320px)] bg-blue-600 hover:bg-blue-700 text-white p-4 rounded-full shadow-lg transition-transform active:scale-95 z-50"
          aria-label="Toggle Assistant"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
          </svg>
        </button>

        {isChatOpen && <ChatAssistant onClose={() => setIsChatOpen(false)} user={user} />}

        <div className="sticky bottom-0 w-full z-10">
          <BottomNav 
            currentScreen={currentScreen} 
            onNavigate={setCurrentScreen} 
          />
        </div>
      </div>
    </div>
  );
};

