                       <p className="text-[10px] font-bold opacity-60 uppercase mb-1">Total Interest ({months} Months)</p>
                       <p className="text-lg font-bold text-yellow-300">{formatCurrency(calculateTotalInterest())}</p>
                     </div>
                   </div>
                   <div className="mt-4 pt-4 border-t border-white/10 flex justify-between items-end">
                      <div>
                        <p className="text-[10px] font-bold opacity-60 uppercase mb-1">Maturity Value</p>
                        <p className="text-xl font-bold">{formatCurrency(parseFloat(investAmount) + calculateTotalInterest())}</p>
                      </div>
                      <div className="text-[10px] font-medium opacity-60 italic">
                        Payout: {getMaturityDate()}
                      </div>
                   </div>
                </div>
              ) : investAmount ? (
                <div className="p-3 bg-red-50 text-red-500 rounded-lg text-xs font-bold text-center border border-red-100">
                  Minimum investment requirement: ₦3,000,000.00
                </div>
              ) : null}

              {/* Signature Upload Section */}
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-2">Verification Signature</label>
                <div className="relative border-2 border-dashed border-gray-200 rounded-xl p-8 hover:border-blue-300 transition-colors bg-gray-50 flex flex-col items-center justify-center cursor-pointer">
                  <input 
                    type="file" 
                    onChange={handleSignatureChange}
                    accept="image/*"
                    className="absolute inset-0 opacity-0 cursor-pointer"
                  />
                  <svg className="w-8 h-8 text-gray-400 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
                  </svg>
                  <p className="text-[10px] font-bold text-gray-500 uppercase">
                    {signature ? signature.name : "Tap to upload digital signature"}
                  </p>
                </div>
              </div>

              <button 
                onClick={handleExecute}
                disabled={!investAmount || parseFloat(investAmount) < 3000000 || !signature || parseFloat(investAmount) > user.balance}
                className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 disabled:text-gray-400 text-white font-bold py-4 rounded-xl shadow-lg transition-all active:scale-95"
              >
                {parseFloat(investAmount) > user.balance ? 'Insufficient Main Balance' : 'Execute Subscription'}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Confirmation Modal */}
      {showConfirmation && (
        <div className="fixed inset-0 z-[60] flex items-end justify-center px-4 pb-20 sm:items-center sm:p-0">
          <div className="fixed inset-0 bg-gray-900/80 backdrop-blur-sm transition-opacity" onClick={() => !isProcessing && setShowConfirmation(false)}></div>

          <div className="bg-white rounded-[2rem] overflow-hidden shadow-2xl transform transition-all sm:max-w-lg sm:w-full animate-slide-up relative">
            <div className="p-8">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-blue-900">Confirm Investment</h3>
                <button onClick={() => setShowConfirmation(false)} className="text-gray-400 hover:text-gray-600 transition-colors">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>

              <div className="space-y-4 mb-8">
                <SummaryItem label="Principal Amount" value={formatCurrency(parseFloat(investAmount))} />
                <SummaryItem label="Duration" value={`${months} Months`} />
                <SummaryItem label="Monthly Interest Rate" value="5.42%" />
                <SummaryItem label="Projected Total Interest" value={formatCurrency(calculateTotalInterest())} highlight />
                <SummaryItem label="Maturity Date" value={getMaturityDate()} />
                <div className="pt-4 border-t border-gray-100 flex justify-between items-center">
                  <span className="text-sm font-bold text-gray-800 uppercase tracking-tighter">Expected Payout</span>
                  <span className="text-2xl font-black text-blue-600 tracking-tighter">
                    {formatCurrency(parseFloat(investAmount) + calculateTotalInterest())}
                  </span>
                </div>
              </div>

              <div className="flex gap-4">
                <button 
                  disabled={isProcessing}
                  onClick={() => setShowConfirmation(false)} 
                  className="flex-1 border-2 border-gray-100 text-gray-400 font-bold py-4 rounded-2xl hover:bg-gray-50 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  disabled={isProcessing}
                  onClick={handleFinalize}
                  className="flex-1 bg-blue-600 text-white font-bold py-4 rounded-2xl shadow-lg hover:bg-blue-700 transition-all flex items-center justify-center gap-2"
                >
                  {isProcessing ? (
                    <>
                      <svg className="animate-spin h-5 w-5 text-white" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      Finalizing...
                    </>
                  ) : 'Confirm & Buy'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Success State */}
      {isSuccess && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center px-4">
          <div className="fixed inset-0 bg-blue-900/90 backdrop-blur-xl"></div>
          <div className="text-white text-center animate-slide-up relative z-10">
            <div className="w-24 h-24 bg-green-500 rounded-full flex items-center justify-center mx-auto mb-6 shadow-2xl animate-bounce">
              <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <h3 className="text-3xl font-bold mb-2">Subscription Successful</h3>
            <p className="text-blue-200 mb-8 max-w-xs mx-auto">Funds moved to your Wealth Portfolio. Your high-yield investment has been activated.</p>
            <button 
              onClick={() => {
                setIsSuccess(false);
                setInvestAmount('');
                setSignature(null);
              }}
              className="bg-white text-blue-900 font-bold px-12 py-4 rounded-2xl shadow-xl active:scale-95 transition-all"
            >
              Back to Portfolio
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

