                          <p className="text-lg font-black text-gray-800">{formatCurrency(inv.amount)}</p>
                        </div>
                        <div className="text-right">
                          <p className="text-[9px] font-bold text-gray-400 uppercase">Maturity Date</p>
                          <p className="text-xs font-bold text-[#0033a0]">{inv.maturityDate}</p>
