      activeInvestments: [newInvestment, ...prev.activeInvestments]
    }));

    const newTx: Transaction = {
      id: `tx-${Date.now()}`,
      name: 'Stanbic Mutual funds Subscription',
      type: 'debit',
      amount: amount,
